{
  "selections": [
    {
      "trait_id": "/core_belief/core_belief_statement",
      "background_ids": ["/childhood_data"],
      "relevance": "상담사가 '들러리'라는 말이 특히 어디가 아팠는지 묻고 있음. '특별한 사람이므로 보통 사람에게 적용되는 대우가 적용되어서는 안 된다'는 핵심 신념이, 자신을 '들러리(조연)'로 격하한 아내의 말에 깊이 상처받는 이유와 직접 연결됨. 성장 배경에서 어머니가 '다른 애들과 급이 다르다'고 반복한 경험이 이 신념의 뿌리."
    },
    {
      "trait_id": "/intermediate_beliefs/assumption_negative",
      "background_ids": ["/childhood_data"],
      "relevance": "'보통 사람들과 같은 취급을 받으면 그저 그런 사람으로 전락한다'는 가설이, '들러리'라는 표현이 촉발하는 공포—즉 자신이 특별하지 않은 평범한 사람으로 환원될 수 있다는 위협—과 연결됨. 내담자가 '억울하다'고만 답하고 고통의 구체적 지점을 회피하는 것도 이 가설이 작동할 때의 방어와 일치."
    },
    {
      "trait_id": "/coping_strategies/1",
      "background_ids": ["/situations/2"],
      "relevance": "내담자가 '내가 가족 건사하려고 얼마나 뛰었는지 알면서'라고 말하며 아내의 문제(감사하지 못함)로 원인을 돌리는 방식이, '관계에서 문제가 생기면 상대의 나약함·능력 부족에서 원인을 찾음'이라는 대처 전략과 일치. 상황 사례 2에서 장모에게 따지고 '제가 뭘 그렇게 잘못했습니까'라고 한 패턴과 동일."
    },
    {
      "trait_id": "/coping_strategies/4",
      "background_ids": [],
      "relevance": "상담사가 '그 질문이 어떻게 들리셨어요?'라고 메타 질문을 했을 때 내담자가 '그냥 답한 거죠 뭐'라고 형식적으로 넘긴 태도가, 통제할 수 없는 자리(상담)를 '시간 낭비'로 규정하고 깎아내리는 대처 전략과 연결됨."
    }
  ]
}

